import{_ as o,o as a,c as r,a0 as t}from"./chunks/framework.DQOulFGV.js";const q=JSON.parse('{"title":"常见问题 (FAQ)","description":"","frontmatter":{},"headers":[],"relativePath":"guide/faq.md","filePath":"guide/faq.md"}'),n={name:"guide/faq.md"};function d(s,e,c,i,l,h){return a(),r("div",null,[...e[0]||(e[0]=[t('<h1 id="常见问题-faq" tabindex="-1">常见问题 (FAQ) <a class="header-anchor" href="#常见问题-faq" aria-label="Permalink to &quot;常见问题 (FAQ)&quot;">​</a></h1><p>整理了关于 KernelEX 的常见使用疑问与技术解答。</p><hr><h3 id="q1-为什么像-top、htop、vim-这类程序在终端中无法正常显示" tabindex="-1">Q1: 为什么像 <code>top</code>、<code>htop</code>、<code>vim</code> 这类程序在终端中无法正常显示？ <a class="header-anchor" href="#q1-为什么像-top、htop、vim-这类程序在终端中无法正常显示" aria-label="Permalink to &quot;Q1: 为什么像 `top`、`htop`、`vim` 这类程序在终端中无法正常显示？&quot;">​</a></h3><p><strong>A</strong>：KernelEX 是一个基于管道（Pipe 重定向 <code>stdin</code>/<code>stdout</code>/<code>stderr</code>）的图形化执行辅助工具，<strong>不是</strong>基于 Linux 原生 PTY 伪终端的完整终端模拟器。因此，依赖 ncurses / 绝对光标移动定位的全屏交互式软件无法正常渲染。KernelEX 主要针对自动化 Shell 脚本、后台服务程序、系统模块刷写及批处理工具。</p><hr><h3 id="q2-为什么二进制程序需要以-so-命名" tabindex="-1">Q2: 为什么二进制程序需要以 <code>.so</code> 命名？ <a class="header-anchor" href="#q2-为什么二进制程序需要以-so-命名" aria-label="Permalink to &quot;Q2: 为什么二进制程序需要以 `.so` 命名？&quot;">​</a></h3><p><strong>A</strong>：在 Android 平台中，通常只有特定受保护分区或 App 私有目录具备二进制执行权限，将 ELF 原生可执行文件命名为 <code>.so</code> 是 Magisk 模块与 Android 极客工具中通用的惯例。KernelEX 原生支持执行 <code>.so</code> 与 <code>.sh</code> 文件，并在调用前自动补齐 <code>chmod 777</code>。</p><hr><h3 id="q3-任务在后台长时间执行时被系统杀掉怎么办" tabindex="-1">Q3: 任务在后台长时间执行时被系统杀掉怎么办？ <a class="header-anchor" href="#q3-任务在后台长时间执行时被系统杀掉怎么办" aria-label="Permalink to &quot;Q3: 任务在后台长时间执行时被系统杀掉怎么办？&quot;">​</a></h3><p><strong>A</strong>：</p><ol><li>请前往「设置」或权限拦截门，点击「<strong>申请忽略电池优化</strong>」，将 KernelEX 添加至系统电池白名单；</li><li>在国内厂商定制系统（如 HyperOS、OriginOS、ColorOS）中，建议在最近任务栏将 KernelEX <strong>加锁</strong>，并开启「允许自启动/关联启动」权限。</li></ol><hr><h3 id="q4-如何恢复默认字体" tabindex="-1">Q4: 如何恢复默认字体？ <a class="header-anchor" href="#q4-如何恢复默认字体" aria-label="Permalink to &quot;Q4: 如何恢复默认字体？&quot;">​</a></h3><p><strong>A</strong>：进入底栏「设置」页面，找到「自定义软件字体」卡片，点击右侧的设置图标进入字体配置对话框，点击「<strong>恢复默认字体</strong>」即可立即重置为内置默认字体。</p><hr><h3 id="q5-「添加到-kernelex」时的「独立文件夹」有什么作用" tabindex="-1">Q5: 「添加到 KernelEX」时的「独立文件夹」有什么作用？ <a class="header-anchor" href="#q5-「添加到-kernelex」时的「独立文件夹」有什么作用" aria-label="Permalink to &quot;Q5: 「添加到 KernelEX」时的「独立文件夹」有什么作用？&quot;">​</a></h3><p><strong>A</strong>：当多个脚本带有同名资源文件（例如 <code>config.json</code> 或辅助二进制）时，如果直接放入同一个目录容易发生文件覆盖。开启独立文件夹功能后，KernelEX 会在 <code>/data/adb/KernelEX/</code> 下以 <code>[名称]_[时间戳]</code> 自动建立子目录进行隔离。</p>',18)])])}const g=o(n,[["render",d]]);export{q as __pageData,g as default};
